<?php

/**
 * AnaItemsTable
 * 
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class AnaItemsTable extends Doctrine_Table {

  /**
   * Returns an instance of this class.
   *
   * @return object AnaItemsTable
   */
  public static function getInstance() {
    return Doctrine_Core::getTable('AnaItems');
  }

  public static function getItem($key = "", $url = "") {
    if ($key != "") {
      $url = rtrim($url, '/') . '/';
      $q = Doctrine_Core::getTable('AnaItems')
              ->createQuery('ai')
              ->leftJoin('ai.AnaProjects ap')
              ->where('ai.item_key=?', $key)
              ->andWhere('ap.url=?', $url)
      ;
      return $q->execute();
      /* $arr = $q->execute()->toArray();

        echo "<pre>";
        print_r ($arr);
       */
    }
  }

}